import re
L=open('The_Method_1_6-2.md',encoding='utf-8').read().split('\n')
starts=[1540,1560,1784,2009,2222,2270,2323,2387,2430,2531,3471,4320,4374,4713,5415,6329,6576,6647,6662,6848,6952,7132,7265]
caps={}
for s in starts:
    i=s-1; buf=[]
    while i<len(L) and L[i].strip():
        buf.append(L[i].strip()); i+=1
    t=' '.join(buf); fig=re.match(r'Figure ([\d.]+)\.',t).group(1); caps[fig]=t
    print(t,'\n')
import json; json.dump(caps,open('caps.json','w'))
EOF

